"""Texts of the report: model summary and a short caption (what it shows / what to expect) per figure."""

TAGLINE = "Loop extrusion × DNA replication × chromatin compartments"

ABOUT = [
    "RepliSage simulates how chromatin loops, DNA replication and compartments evolve together through the cell cycle. "
    "Loop extruding factors (LEFs, e.g. cohesin) grow loops until they meet CTCF sites. Replication forks move through the DNA "
    "and act as moving barriers for LEFs. Every bead also carries an epigenetic state that is spread behind the replication fork "
    "and organises A/B compartments.",
    "A Monte Carlo (Metropolis) simulation produces the time evolution of loops, replication and epigenetic states. "
    "Molecular dynamics (OpenMM) can then turn each Monte Carlo state into a 3D structure, with two sister chains once replication is modelled.",
]
STAGES = [("Loop extrusion", "LEFs with two legs (m, n) bind CTCF sites and extrude loops."),
          ("Replication", "Origins fire from the initiation rate I(x,t); forks move in both directions."),
          ("Compartments", "One of five epigenetic states per bead (−2…2): A-like (open) if above 0, B-like (closed) if below 0."),
          ("3D structure", "OpenMM builds the chromatin chain(s) from every sampled state.")]
EPI_INTRO = ("Think of every bead as a small stretch of chromatin wearing a colour. The colour is its epigenetic state, a number from −2 to +2: positive (red) means open, active, A-like chromatin; negative (blue) means closed, quiet, B-like chromatin; 0 means undecided. "
             "Beads like to share the colour of their neighbours and of the beads their loops connect them to, and replication timing nudges early-replicating regions towards A. "
             "The figures below look at this colouring in different ways: how it is arranged along the genome, how it changes while the DNA is copied, and how orderly it is. "
             "Words from physics are explained in the 'How the quantities are defined' box near the top of the report.")
EQ = [("$H = H_{le} + H_{rep} + H_{epi}$", "Total energy of a state. A Monte Carlo move is accepted with probability $\\min(1, e^{-\\Delta H / T_{mc}})$, where $T_{mc}$ is the Monte Carlo temperature."),
      ("$H_{le} = H_{fold} + H_{cross} + H_{bind}$", "Loop extrusion: folding favours long loops, crossing penalises LEFs that cross, binding rewards legs $(m_i, n_i)$ sitting on CTCF sites."),
      ("$H_{rep}$", "Penalty for loops that straddle a replication fork."),
      ("$H_{epi}$", "Epigenetic energy of the bead states $s_k \\in \\{-2, \\dots, 2\\}$: a replication-timing field plus coupling between beads linked by the backbone or by loops.")]
READ = "Grey band = burn-in (discarded). Red band = S phase (replication). Red = A compartment (open, positive epigenetic states), blue = B compartment (closed, negative epigenetic states). Orange / teal = left / right LEF legs and CTCF sites."

# fid -> (title, what it shows, what to expect)
CAP = {
 "loops_input": ("CTCF binding input", "Left: raw CTCF sites on the beads (top) and the smoothed profiles L (orange, up) and R (teal, down) that the model uses (bottom). Right: loop lengths (BEDPE) or peak strengths, and the distance between neighbouring anchors.", "Smoothing widens each site to about σ beads without changing its total weight. Peaks of L and R are where LEF legs stall; clustered anchors collapse into one bead at coarse resolution."),
 "mc_energy": ("Energies", "Total, folding and binding energy over MC steps: trace (grey) and moving average (black).", "Stable fluctuations after burn-in. With replication, a shift can appear in S phase as forks restrict loops."),
 "mc_energy_potts": ('Epigenetic energy and average epigenetic state', 'Two curves over the simulation. Orange: the epigenetic energy, a score of how comfortable the colours of the beads are with each other (lower = more comfortable). Green: the average epigenetic state, the mean colour of all beads (above 0 = more A-like, below 0 = more B-like).', 'Both settle during G1. They shift while replication runs, because forks change the colours, and settle again in G2/M.'),
 "mc_distributions": ("Distributions", "Box plot per phase of energy, folding and loop length: box = middle 50 %, line = median, dot = mean, whiskers = 5th to 95th percentile. One histogram without replication.", "Overlapping boxes mean the phase barely matters; shifted ones show the effect of replication."),
 "mc_convergence": ("Chain diagnostics", "Geweke z (start vs end of chain), effective sample size share (ESS/n) and split R̂ for each observable.", "|z| < 2, R̂ < 1.01 and ESS/n of several percent mean a well-mixed chain. Red bars flag problems: run longer."),
 "mc_replicas": ("Replica comparison", "Same observables across independent replicas (different seeds), with split R̂ between them.", "Replicas overlap; R̂ close to 1 means they agree."),
 "mc_acf": ("Autocorrelation", "How quickly samples forget their past. T_ρ = integrated autocorrelation time (samples).", "Curves fall to zero within a few lags. Large T_ρ means correlated samples and fewer independent ones."),
 "mc_running": ("Running mean", "Mean after burn-in as samples accumulate. Band = final mean ± 2 Monte Carlo standard errors.", "The curve settles inside the band. A drift means the run is too short."),
 "rep_violations": ("Fork conflicts", "Number and strength of loops straddling a replication fork during S phase.", "Low when the replication penalty is strong. Bursts appear as forks push LEFs."),
 "lef_traj": ("LEF kymograph and mean loop size", "Top: a sample of LEFs, one colour each; a vertical bar joins the two legs of a bound LEF at every recorded time (a kymograph = position against time). Bars on the right: CTCF sites (orange left, teal right). Dashed line: replication front. Bottom: mean loop size over time, for all LEFs (unbound count as 0, grey) and for bound LEFs only (red); the side histogram shows its spread after burn-in.", "Persistent bars of one colour at CTCF sites mark stable loops; short, scattered bars mean fast turnover. Watch whether the mean size changes when the front passes (S phase)."),
 "ctcf_occupancy": ("Loop occupancy and CTCF orientation (preferential binding)", "Top: occupancy of every bead by loops (each loop adds its strength to all beads between its two anchors, so nested loops stack; scaled to 0-1), the relative LEF loading weight derived from it, and the CTCF strength. Bottom: orientation of each CTCF site: left-ward (orange) or right-ward (teal) triangle, marker size = strength, opacity = confidence.", "Loading weight follows the occupancy: LEFs start mostly inside loop-spanned areas and rarely in loop-naked ones. Opaque markers have a confident orientation, faint ones are mixed or unknown."),
 "model_maps": ("Heatmaps from the simulation state alone", "Columns: G1, S, G2/M. Row 1: mean LEF contact map (count of loops joining two beads, Gaussian-blurred, log colour). Row 2: product s(i)·s(j) of the mean epigenetic state of beads i and j (red = same compartment). Row 3: (P + row 1) · exp(κ · row 2), with baseline P = 1 / (1 + |i − j|). Operations are listed under 'How to read it'.", "Row 1 should show loop dots and stripes at CTCF anchors, row 2 plaid compartments, row 3 both patterns together. Changes between columns show what replication does."),
 "lef_coverage": ("Loop coverage", "Number of loops over every bead (white = none, black = many). Right: time average.", "Dark bands at strong domains and gaps between them; a stable profile after burn-in."),
 "loop_length": ("Loop length", "Mean loop length with 95 % CI across LEFs (left); box plot per phase on a log axis (right; zeros dropped).", "Constant after burn-in. A shift in S phase means forks shorten or reshape loops."),
 "violin_loop_length": ("Loop length by phase", "Distribution of all loop lengths in G1, S and G2/M.", "Similar shapes if replication does not affect loops."),
 "lef_binding": ("LEF anchoring", "Top: share of bound LEFs and of legs on CTCF sites. Bottom: legs per bead for left (orange) and right (teal) legs, triangles = CTCF.", "Leg occupancy peaks at matching CTCF sites; a stronger binding coefficient raises the on-CTCF share."),
 "rep_forks": ("Replication forks", "Left: replicated DNA (green) in genome × time. Right: active forks (blue) and inferred origins (red triangles).", "Forks spread from origins in both directions; early regions replicate first; everything is replicated at the end."),
 "rep_fraction": ("Replicated fraction", "Fraction of the region replicated over S phase (T10, T50, T90 marked) and number of active forks.", "A smooth S-shaped curve; forks rise as origins fire and fall as forks merge."),
 "rep_initiation": ("Initiation rate", "I(x,t): chance that an origin fires at position x and time t. Top: where origins fire. Right: when.", "Diagonal bands: early regions fire early. Triangles (origins) sit on dark bands."),
 "rep_timing": ("Timing check", "Replication earliness from the data and from the simulation along the region (left); bead by bead (right) with Spearman ρ.", "Curves overlap and ρ is close to 1."),
 "epi_traj": ('Epigenetic state of every bead over time', 'Every row is a bead along the region and every column a moment in time. Red = open, active, A-like chromatin; blue = closed, quiet, B-like chromatin; white-grey = undecided. The dashed line is the replication front.', 'Wide bands of one colour in G1 are compartments. Behind the dashed front in S phase the colours may change: that is the effect of copying the DNA.'),
 "epi_sorted": ('Beads ordered by replication timing', 'The same colour map, but the beads are re-ordered from the earliest to the latest replicating one instead of along the genome.', 'If timing organises the compartments, the early beads at the top stay red and the late beads at the bottom stay blue, and changes start at the top, where forks arrive first.'),
 "epi_fractions": ('Share of beads in each state', 'Top: how many beads wear each of the five colours (−2 and −1 blue, 0 neutral, +1 and +2 red). Bottom: all A-like beads (positive) against all B-like beads (negative).', 'Roughly steady in G1, a shift during S phase, and steady again in G2/M. A rising A share means that replication turns beads towards the open state.'),
 "epi_switching": ('How many beads change compartment', 'Left: for pairs of moments a fixed time apart, the share of beads that flipped from B to A (red) or A to B (blue). Right: how many beads moved between B, neutral and A between the start and the end of S.', 'More flipping in the S band than outside it means replication is what shakes the compartments up. More red than blue means A grows.'),
 "epi_switch_bars": ('Beads switching during S phase', 'Left: the share of beads in B, neutral and A at the start and at the end of S phase. Right: the share that switched B to A, A to B, or did not change.', 'Most beads stay as they are. The difference between the red and the blue bar is the net change of the A compartment.'),
 "epi_switch_map": ("Switching along the genome", "Along the region: when each bead replicates, its compartment at the start and the end of S phase, and which beads switched (red B to A, blue A to B). Below: the share of beads that switch among the earliest, middle and latest replicating thirds.", "Early regions tend to be A and late ones B. If early DNA switches towards A more than late DNA does, timing is steering the compartments."),
 "epi_same_sign": ('Do loops join beads of the same colour?', 'The share of loops whose two ends sit on beads of the same sign, both A-like or both B-like (teal), or of opposite sign (orange). Right: the same share per phase.', 'A high teal share means loops stay inside one compartment. A drop in S phase means replication makes loops reach across compartments.'),
 "violin_same_sign": ('Same-colour loops per phase', 'Box plots of the share of loops joining beads of the same sign in G1, S and G2/M.', 'A lower box in S phase means loops link beads of different compartments more often while replication runs.'),
 "epi_order": ("How ordered are the colours? (1)", "Three simple measures of how tidy the colour pattern is, over time; the grey note above each panel says what the values mean and dotted lines mark reference values. Top: how strongly one colour dominates. Middle: the Binder cumulant, which separates a lopsided colour mix from an evenly mixed one. Bottom: how often two linked beads (chain neighbours or loop partners) have the same colour.", "Compartments forming means higher dominance and higher agreement between linked beads. Random speckles give values near the dotted lines."),
 "epi_order2": ("How ordered are the colours? (2)", "Two more measures. Top: the share of beads wearing the most common colour. Bottom: the mixing (entropy) of the colours, high when all five are used about equally and low when a few dominate.", "Mixing falls and the most common colour grows as compartments become more ordered."),
 "md_dynamics": ("MD energies", "Potential and kinetic energy (left) and temperature (right) of the last MD run.", "Energies settle and the temperature stays near the target."),
 "md_structure": ("3D size and shape", "Radius of gyration, mean pair distance and end-to-end distance of each sampled 3D structure.", "Stable fluctuations; compaction visible as drops."),
 "md_compaction": ("Compaction through the cell cycle", "Top: radius of gyration, convex-hull volume, contacts and distance between the two sister centroids of every sampled structure, with G1, S and G2/M shaded. Bottom: phase means relative to G1 (± s.d.). Radius of gyration = root-mean-square distance of the beads from the centre of mass; hull volume = volume of the smallest convex shape enclosing the beads.", "Expected: decompaction in S (larger size, fewer contacts, as replicated chromatin unfolds and the sisters form) and re-compaction in G2/M (size and volume drop, contacts rise, sisters move apart). The first G1 structures are still relaxing from the initial conformation, so judge G1 after it has levelled off (longer runs make this negligible)."),
 "md_structure2": ("3D shape and contacts", "Asphericity, number of contacts and convex-hull volume of each sampled structure.", "Stable fluctuations after equilibration."),
}

# new diagnostic figures: (title, shows, expect) and a longer "how to read it" text
CAP.update({
 "fork_events": ("LEF-fork encounters in S phase", "Left: cumulative fraction of encounters, pushes and removals as S phase proceeds (dashed = events spread evenly in time). Middle: number of pushes and removals in each tenth of S phase. Right: pushing and removal rates, i.e. events per encounter.", "Curves above the diagonal mean events come early in S phase; a high removal rate means forks mostly dislodge LEFs rather than push them."),
 "hic_validation": ("Model against Hi-C", "Top: the Hi-C map, the simulated map(s) and a triangle with Hi-C above and the model below the diagonal. Bottom: contact decay with distance P(s), insulation (domain boundaries) and the A/B compartment track.", "Matching dots and domains show that loops and CTCF sites are placed right; matching checkerboard and A/B track show that the epigenetic compartments are right."),
 "energy_budget_phases": ("Energy budget over the cell cycle", "Left: mean of every soft energy term of the model in G1, S and G2/M (whiskers = SD of the fluctuations). Middle: how each term changes relative to G1. Right: the terms over time. Negative energy = favourable.", "A term that grows in S phase is the one that replication perturbs; the total is what the Monte Carlo minimises."),
 "free_energy_landscape": ("Free-energy landscapes", "F(x) = −T ln P(x) of the mean loop length (and, with replication, the mean epigenetic state): how likely the system is to be found at each value, one curve per phase.", "Low F = frequently visited. A shifted minimum or a new second minimum between phases is a change of the preferred fold."),
 "loop_nesting": ("Families of loops over the cell cycle", "Left: loops per sample by family: orphans (isolated), parents (hold other loops) and children of order 1, 2, 3+ (inside that many loops). Middle: share of each family in G1, S and G2/M. Right: mean and deepest nesting order over time.", "More loops in parent / child families means a more nested, hierarchical fold; compare the phases to see how replication changes it."),
 "loop_parents_children": ("Parents and children", "Left: length of every parent loop against the number of loops inside it (line = binned mean). Middle: loop length by family. Right: child length divided by the length of the loop enclosing it, per phase.", "A ratio near 1 means children almost fill their parent; small ratios mean many short loops inside a long one."),
 "mc_stationarity": ("Stationarity check", "Density of each observable in the first and in the second half of the stationary part of the run.", "Two overlapping curves: the chain has settled, so its statistics do not depend on when you look."),
 "mc_mcse": ("Error vs samples", "Left: Monte Carlo standard error relative to the spread (MCSE / SD) as samples accumulate. Right: effective samples, the number of independent draws the chain is worth.", "Both curves follow the dashed line at first and bend away from it: samples are correlated, so each one is worth less than an independent draw."),
 "mc_rolling": ("Rolling statistics", "Rolling mean with a band of one standard deviation for energy and loop length, and the rolling autocorrelation time of the energy.", "Flat mean and band in G1; a change at S phase; a stable autocorrelation time."),
 "mc_correlation": ("Observable correlations", "Left: rank correlation between all observables after burn-in. Right: energy against mean loop length, coloured by time.", "Folding energy follows loop length strongly; the colour gradient shows how the system moves between phases."),
 "mc_budget": ("Energy budget", "Left: the energy terms over time (Other = loop crossing and replication barrier). Right: mean of each term in G1, S and G2/M.", "Folding and binding dominate and stay steady; Other stays near zero if loops avoid crossing and respect forks."),
 "lef_dynamics": ("LEF binding dynamics", "Left: fraction of LEFs bound over time. Right: how long LEFs stay bound before they unbind, on a log axis.", "A steady bound fraction and a broad lifetime distribution with a long tail (stable CTCF-anchored loops)."),
 "epi_domains": ('Compartment domains', 'A domain is an unbroken stretch of beads that are all A-like or all B-like. Left: how long these stretches are in each phase. Right: the average stretch length over time.', 'Stretches of a few to tens of beads. Shorter stretches in S phase mean replication breaks compartments into pieces; longer ones in G2/M mean they merged again.'),})
HOW = {
 "mc_energy": "Faint line: every recorded sample. Bold line and band: moving average and one standard deviation. Grey = burn-in, red band = S phase. After burn-in the bold line should wobble around a flat level. A steady drift means the run is too short; raise BURNIN or N_STEPS. A jump at the S-phase edges is expected: forks change the allowed loops.",
 "mc_distributions": "Each box summarises one phase: the box spans the middle 50 % of the samples (interquartile range), the line is the median, the dot the mean and the whiskers the 5th and 95th percentiles. Phases whose boxes barely overlap differ clearly. Without replication a single histogram is shown. Wide violins mean large fluctuations, not an error.",
 "mc_convergence": "Left: Geweke z compares the start and the end of the stationary part; bars inside the grey band (between -2 and 2) pass. Middle: effective sample size as a percentage of the samples; low values mean strongly correlated samples, so increase MC_STEP or run longer. Right: split R-hat; below 1.01 (teal) is good, gold is borderline, red means the halves of the chain disagree.",
 "mc_acf": "Autocorrelation is the correlation of a series with itself shifted by a lag. It starts at 1 and should die out. The number T_ρ in the legend is the integrated autocorrelation time: roughly how many consecutive samples carry the information of one independent sample. If the curve stays high for tens of lags, raise MC_STEP so that recorded states are further apart.",
 "mc_running": "The line is the average of all samples up to that step. It should settle onto the horizontal line, inside the grey band of plus or minus two Monte Carlo standard errors. If it keeps sliding the estimate is not converged. The faint line behind is the raw series.",
 "mc_stationarity": "A small KS statistic (Kolmogorov-Smirnov distance, 0 = identical, 1 = completely different) means the two halves look alike. Values above about 0.2 with visibly shifted curves say the chain was still moving: lengthen the burn-in.",
 "mc_mcse": "For independent samples the error falls as 1 over the square root of n (dashed line). Correlated chains fall more slowly, and the gap between the curves and the dashed line is the price of correlation. On the right, the effective sample size should keep growing as you add samples; if it flattens, more steps do not help and something is stuck.",
 "mc_rolling": "Moving windows reveal slow changes that a global average hides. The third panel estimates the autocorrelation time in each window: a sudden rise means the dynamics became sluggish (for example, loops locked in place by forks).",
 "mc_correlation": "Rank (Spearman) correlation is 1 when two observables rise together, -1 when one rises as the other falls, and 0 when unrelated. Strong blocks tell you which observables carry the same information, so you can pick one to monitor. Colour in the scatter runs from early to late steps: separate colour clouds show distinct phases.",
 "mc_budget": "The total energy is the sum of folding, binding, epigenetic and the rest. Terms with large swings drive the dynamics; terms near zero are not constraining the system. The bars compare phases: a bar that changes in S phase is the part of the model that responds to replication.",
 "lef_dynamics": "Bound means a LEF has legs on two different beads. A lifetime is the time between a LEF binding and unbinding. Short lifetimes mean frequent rebinding (loops form and disappear); a long tail means some loops are stable, typically anchored at CTCF sites. In S phase, forks may shorten lifetimes by pushing loops away.",
}
def how_for(fid): return HOW.get(fid, "")

def cap_for(fid):
    if fid in CAP: return CAP[fid]
    if fid == "md_heat_phases": return ("Contact maps by phase", "Mean of 1/(distance + 1) between beads over the structures of each phase (G1, S, G2/M) on one shared colour scale; warm = close.", "Domains (squares) along the diagonal and loop dots; compare the S and G2/M maps with G1 to see what replication does.")
    if fid.startswith("md_heat_"): return ("Contact map", "Mean of 1/(distance + 1) between beads over the structures of one phase (dark = close).", "Domains (squares) along the diagonal and loop dots; the S-phase map shows the effect of replication.")
    return (fid.replace("_", " ").capitalize(), "", "")

